INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(1584000, 1584, 0, 1, 0, 0, 0, 0, 'Blackrock Depths', 'Immense volcanic tunnels at the roots of Blackrock Mountain, the home of the Dark Iron dwarves and of the black forge where they smelt their namesake ore. Much of it was built by the architect Franclorn Forgewright. It holds a prison, an arena, a tavern and Shadowforge City, the vast capital of the Dark Irons.\n\nEmperor Dagran Thaurissan rules it, the latest of a line of sorcerer-thanes who have served in the shadow of Ragnaros since his ancestor summoned the Firelord. The Dark Irons labour for Ragnaros''s elementals, and worship them, and are led by them towards ever more dangerous and apocalyptic deeds.', 'warcraft.wiki.gg: Blackrock Depths (introduction, History)'),
(1584001, 1584, 1, 1, 0, 0, 0, 0, 'The Detention Block', 'The Dark Irons'' prison, run with the help of the Twilight''s Hammer. Its cells hold enemies of every kind, Horde officers of the Kargath Expeditionary Force and Alliance agents among them, and its interrogator is a woman of the Twilight''s Hammer.', 'warcraft.wiki.gg: Blackrock Depths (Dungeon denizens); warcraft.wiki.gg: General Angerforge'),
(1584002, 1584, 1, 2, 0, 0, 0, 0, 'The Ring of Law', 'The Dark Irons'' arena of justice, overseen by High Justice Grimstone. Anyone who steps into it is sentenced on the spot, and has to survive whatever beasts and champions the crowd''s justice sends against them.', 'warcraft.wiki.gg: Ring of Law'),
(1584003, 1584, 1, 3, 0, 0, 0, 0, 'The Halls of the Law and Franclorn''s Monument', 'Halls of fire elementals and Dark Iron hounds beyond the prison. Past the arena stands the monument to Franclorn Forgewright, before which a tauren shaman of the Twilight''s Hammer kneels.', 'warcraft.wiki.gg: Lord Roccor; warcraft.wiki.gg: Pyromancer Loregrain'),
(1584004, 1584, 1, 4, 0, 0, 0, 0, 'The Dark Iron Highway', 'The great road through the depths, with a molten giant born of Ragnaros''s fires at one end, and the West Garrison, where the venerable General Angerforge commands the Dark Iron armies.', 'warcraft.wiki.gg: Bael''Gar; warcraft.wiki.gg: General Angerforge'),
(1584005, 1584, 1, 5, 0, 0, 0, 0, 'The Manufactory', 'The golem factory of the Dark Irons, full of technicians and their creations, ruled from a private chamber by the Golem Lord.', 'warcraft.wiki.gg: Golem Lord Argelmach'),
(1584006, 1584, 1, 6, 0, 0, 0, 0, 'The Grim Guzzler', 'A two-storey tavern in Shadowforge City, packed with drunken patrons who are friendly enough, until someone breaks the kegs. Its ale is famous; one Hurley Blackbreath stole the recipe for it, and both Ragnar Thunderbrew and the Horde would like it back. It is said the Grim Guzzler and its Brewfest are worth a detour into the depths of the world.', 'warcraft.wiki.gg: Grim Guzzler; warcraft.wiki.gg: Hurley Blackbreath'),
(1584007, 1584, 1, 7, 0, 0, 0, 0, 'Shadowforge City', 'The capital of the Dark Irons: the Hall of Crafting and the Black Anvil, guarded by the fire elemental Lord Incendius; the Black Vault, the Dark Irons'' bank; and the homes of their architects and nobles. Elite warriors and Twilight cultists walk its streets among the common citizens.', 'warcraft.wiki.gg: Lord Incendius; warcraft.wiki.gg: Black Vault; warcraft.wiki.gg: Blackrock Depths (Dungeon denizens)'),
(1584008, 1584, 1, 8, 0, 0, 0, 0, 'The Lyceum and the Summoners'' Tomb', 'In the Chamber of Enchantment, an envoy of Ragnaros''s Flamewakers holds audience. Nearby, in the Summoners'' Tomb, the Seven lie: the patriarchs of the Dark Iron nation who summoned Ragnaros with Thaurissan, and died doing it.', 'warcraft.wiki.gg: Ambassador Flamelash; warcraft.wiki.gg: The Seven'),
(1584009, 1584, 1, 9, 0, 0, 0, 0, 'The Imperial Seat', 'The throne room of the Emperor at the heart of Shadowforge City, reached through the Iron Hall, where a molten giant guards the way and the statues breathe fire.', 'warcraft.wiki.gg: Magmus'),
(1584030, 1584, 2, 1, 0, 0, 0, 0, 'High Interrogator Gerstahn', 'A Twilight''s Hammer interrogator who serves the Dark Irons in their prison, and is very good at it.', 'warcraft.wiki.gg: Blackrock Depths (Lower City)'),
(1584031, 1584, 2, 2, 0, 0, 0, 0, 'Lord Roccor', 'A lava elemental who guards the Halls of the Law.', 'warcraft.wiki.gg: Lord Roccor'),
(1584032, 1584, 2, 3, 0, 0, 0, 0, 'Pyromancer Loregrain', 'A tauren shaman of the Twilight''s Hammer, who kneels before the monument of Franclorn Forgewright.', 'warcraft.wiki.gg: Pyromancer Loregrain'),
(1584033, 1584, 2, 4, 0, 0, 0, 0, 'Bael''Gar', 'A molten giant at one end of the Dark Iron Highway, "a being of pure flame, born of the fires of Ragnaros".', 'warcraft.wiki.gg: Bael''Gar'),
(1584034, 1584, 2, 5, 0, 0, 0, 0, 'General Angerforge', 'The venerable general of the Dark Iron armies, who commands from the West Garrison. His forces slaughtered the 109th division of the Kargath Expeditionary Force, and the Horde has not forgotten.', 'warcraft.wiki.gg: General Angerforge'),
(1584035, 1584, 2, 6, 0, 0, 0, 0, 'Golem Lord Argelmach', 'Master of the Manufactory, guarded by his elite golems, who calls every technician and construct in the factory to his defence when threatened.', 'warcraft.wiki.gg: Golem Lord Argelmach'),
(1584036, 1584, 2, 7, 0, 0, 0, 0, 'Fineous Darkvire', 'The Chief Architect of Shadowforge City, who was given Franclorn Forgewright''s hammer Ironfel when the great architect died. His reputation is poor; it may not be all his own doing.', 'warcraft.wiki.gg: Fineous Darkvire'),
(1584037, 1584, 2, 8, 0, 0, 0, 0, 'Lord Incendius', 'A fire elemental who guards the Black Anvil, where the Dark Irons forge their dark iron.', 'warcraft.wiki.gg: Lord Incendius'),
(1584038, 1584, 2, 9, 0, 0, 0, 0, 'Ambassador Flamelash', 'A Flamewaker, envoy of Ragnaros''s lieutenant Sulfuron Harbinger, who holds court in the Chamber of Enchantment, his burning spirits about him.', 'warcraft.wiki.gg: Ambassador Flamelash'),
(1584039, 1584, 2, 10, 0, 0, 0, 0, 'The Seven', 'Dark Iron dwarves of great knowledge and power, the patriarchs of their nation, who summoned Ragnaros with Sorcerer-Thane Thaurissan and died doing it. Their people were enslaved because of them, yet their spirits seem to think the Firelord''s coming a blessing.', 'warcraft.wiki.gg: The Seven'),
(1584040, 1584, 2, 11, 0, 0, 0, 0, 'Magmus', 'A molten giant who guards the Iron Hall and the way to the Emperor''s seat.', 'warcraft.wiki.gg: Magmus'),
(1584041, 1584, 2, 12, 0, 0, 0, 0, 'Emperor Dagran Thaurissan', 'Emperor of the Dark Iron clan, descendant of the sorcerer-thane who summoned Ragnaros, who has pledged his people to the Firelord''s service. His wife is Moira, daughter of King Magni Bronzebeard, taken by his order; Magni believes she is under a spell, and has sent agents to kill the Emperor and bring her home. Moira, who has come to love him, and carries his heir, may not want to be rescued.', 'warcraft.wiki.gg: Emperor Dagran Thaurissan; warcraft.wiki.gg: Blackrock Depths (World of Warcraft); warcraft.wiki.gg: Moira Thaurissan'),
(1584042, 1584, 2, 13, 0, 0, 0, 0, 'Hurley Blackbreath', 'A Dark Iron who stole a famous ale recipe and hides out in the Grim Guzzler. The surest way to bring him running is to break his kegs.', 'warcraft.wiki.gg: Hurley Blackbreath');
